Kembalikan jawaban langsung (non-streaming)
 fetch('https://puruboy-api.vercel.app/api/chat/completions', {
     method: 'POST',
     headers: { 'Content-Type': 'application/json' },
     body: JSON.stringify({
         model: 'deepseek-chat',
         messages: [{ role: 'user', content: 'Halo, apa itu Next.js?' }]
     })
 }).then(res => res.json()).then(console.log);

Streaming SSE + model reasoning
 fetch('https://puruboy-api.vercel.app/api/chat/completions', {
     method: 'POST',
     headers: { 'Content-Type': 'application/json' },
     body: JSON.stringify({
         model: 'deepseek-reasoner',
         stream: true,
         messages: [
             { role: 'system', content: 'Jawab singkat.' },
             { role: 'user', content: 'Jelaskan fotosintesis' }
         ]
     })
 }).then(res => {
     const reader = res.body.getReader();
     const dec = new TextDecoder();
     (async () => {
         while (true) {
             const { done, value } = await reader.read();
             if (done) break;
             console.log(dec.decode(value));
         }
     })();
 });

